[
  {
    "namespace": "manifest",
    "types": [
      {
        "$extend": "WebExtensionManifest",
        "properties": {
          "chrome_settings_overrides": {
            "type": "object",
            "optional": true,
            "additionalProperties": {
              "$ref": "UnrecognizedProperty"
            },
            "properties": {
              "search_provider": {
                "type": "object",
                "optional": true,
                "additionalProperties": {
                  "$ref": "UnrecognizedProperty"
                },
                "properties": {
                  "name": {
                    "type": "string",
                    "preprocess": "localize"
                  },
                  "keyword": {
                    "optional": true,
                    "choices": [
                      {
                        "type": "string",
                        "preprocess": "localize"
                      },
                      {
                        "type": "array",
                        "items": {
                          "type": "string",
                          "preprocess": "localize"
                        },
                        "minItems": 1
                      }
                    ]
                  },
                  "search_url": {
                    "type": "string",
                    "format": "url",
                    "pattern": "^https://.*$",
                    "preprocess": "localize"
                  },
                  "favicon_url": {
                    "choices": [
                      {
                        "type": "string",
                        "format": "relativeUrl",
                        "max_manifest_version": 2
                      },
                      {
                        "type": "string",
                        "format": "strictRelativeUrl"
                      }
                    ],
                    "optional": true,
                    "preprocess": "localize"
                  },
                  "suggest_url": {
                    "type": "string",
                    "optional": true,
                    "pattern": "^https://.*$|^$",
                    "preprocess": "localize"
                  },
                  "instant_url": {
                    "type": "string",
                    "optional": true,
                    "format": "url",
                    "preprocess": "localize",
                    "deprecated": "Unsupported on Thunderbird."
                  },
                  "image_url": {
                    "type": "string",
                    "optional": true,
                    "format": "url",
                    "preprocess": "localize",
                    "deprecated": "Unsupported on Thunderbird."
                  },
                  "search_url_get_params": {
                    "type": "string",
                    "optional": true,
                    "preprocess": "localize",
                    "description": "GET parameters to the search_url as a query string."
                  },
                  "search_url_post_params": {
                    "type": "string",
                    "optional": true,
                    "preprocess": "localize",
                    "description": "POST parameters to the search_url as a query string."
                  },
                  "suggest_url_get_params": {
                    "type": "string",
                    "optional": true,
                    "preprocess": "localize",
                    "description": "GET parameters to the suggest_url as a query string."
                  },
                  "suggest_url_post_params": {
                    "type": "string",
                    "optional": true,
                    "preprocess": "localize",
                    "description": "POST parameters to the suggest_url as a query string."
                  },
                  "instant_url_post_params": {
                    "type": "string",
                    "optional": true,
                    "preprocess": "localize",
                    "deprecated": "Unsupported on Thunderbird."
                  },
                  "image_url_post_params": {
                    "type": "string",
                    "optional": true,
                    "preprocess": "localize",
                    "deprecated": "Unsupported on Thunderbird."
                  },
                  "search_form": {
                    "type": "string",
                    "optional": true,
                    "format": "url",
                    "pattern": "^https://.*$",
                    "preprocess": "localize"
                  },
                  "alternate_urls": {
                    "type": "array",
                    "items": {
                      "type": "string",
                      "format": "url",
                      "preprocess": "localize"
                    },
                    "optional": true,
                    "deprecated": "Unsupported on Thunderbird."
                  },
                  "prepopulated_id": {
                    "type": "integer",
                    "optional": true,
                    "deprecated": "Unsupported on Thunderbird."
